// Read Claude's answer: the draft, and the values it filled for the rows the
// job's "fill" lists.
//
// With no rows to fill, the whole answer is the draft, as it always was. With
// rows to fill, Claude puts the draft inside <result></result> and each value
// in <field name="NAME">VALUE</field>. Only names in the job's "fill" are
// read (the first of each), and each is made to fit its row: a number, one of
// a choice's answers, yes or no, or text up to 4,000 characters. A value that
// doesn't fit is left out. Every field tag is taken out of the draft, even one
// Claude wrote inside <result>, so its markup never lands on the step.
//
// Nodes that save Claude's draft read "draft" from here, never "Do the
// work"'s raw answer, which may hold the field tags. It reads the AI step by
// name: if you rename it, rename it here.

const answer = $('Do the work').first().json;
const text = (answer.content || [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();

const body = $('Scallle job').first().json.body;
const fill = (Array.isArray(body.fill) ? body.fill : [])
  .filter((f) => f && typeof f.name === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(f.name))
  .slice(0, 20);
if (fill.length === 0) return [{ json: { draft: text } }];

const coerce = (raw, field) => {
  const value = raw.trim();
  if (!value) return undefined;
  if (field.type === 'number') {
    const n = Number(value);
    return Number.isFinite(n) ? n : undefined;
  }
  if (field.type === 'boolean') {
    const word = value.toLowerCase();
    if (word === 'yes' || word === 'true') return true;
    if (word === 'no' || word === 'false') return false;
    return undefined;
  }
  if (field.type === 'choice') {
    const choices = Array.isArray(field.choices) ? field.choices.filter((c) => typeof c === 'string') : [];
    // A choice row with no answers listed: Scallle matches it to the row.
    if (choices.length === 0) return value.slice(0, 4000);
    return choices.find((c) => c.trim().toLowerCase() === value.toLowerCase());
  }
  return value.slice(0, 4000);
};

const FIELD_TAG = /<field\s+name\s*=\s*"([^"]*)"\s*>([\s\S]*?)<\/field>/g;
const fields = {};
for (const match of text.matchAll(FIELD_TAG)) {
  const field = fill.find((f) => f.name === match[1]);
  if (!field || Object.prototype.hasOwnProperty.call(fields, field.name)) continue;
  const value = coerce(match[2], field);
  if (value !== undefined) fields[field.name] = value;
}
const tagged = /<result>([\s\S]*?)<\/result>/.exec(text);
const draft = (tagged ? tagged[1] : text).replace(FIELD_TAG, '').trim();
return [{ json: Object.keys(fields).length > 0 ? { draft, fields } : { draft } }];

// Turn Claude's answer into the result Scallle expects.
//
// Only the text of the answer goes back (thinking blocks are skipped). A
// refusal, a cut-off answer or an empty one is reported as a failure in one
// plain sentence, so a person picks the step up in Scallle.
//
// The draft, and any values for the rows the job's "fill" lists, come from
// "Read the answer". Only those names go back, as text (up to 4,000
// characters), a number or true/false, at most 20. With no rows to fill, the
// result is Claude's whole answer, as it always was.
//
// It reads the AI step and "Read the answer" by name, so app nodes that save
// the draft can go between "Real run, not a test?" and here. If you rename
// either, rename it here.

const answer = $('Do the work').first().json;
const read = $('Read the answer').first().json;
const failed = (sentence) => [{ json: { status: 'error', error_message: sentence } }];

// Check why Claude stopped before reading what it wrote.
if (answer.stop_reason === 'refusal') {
  return failed('Claude declined to work on this item, so there is no result. Please do this step by hand.');
}
if (answer.stop_reason === 'max_tokens') {
  return failed("Claude's answer was cut off at the AI step's length limit. Ask for a shorter result in the step's procedure, or raise 'Maximum Number of Tokens' on the AI step in n8n a little.");
}

const text = (answer.content || [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();
if (!text) {
  return failed('Claude returned an empty answer, so there is no result. Please do this step by hand.');
}

// Only the rows the job asked to fill.
const fill = Array.isArray($('Scallle job').first().json.body.fill) ? $('Scallle job').first().json.body.fill : [];
const filled = read.fields && typeof read.fields === 'object' ? read.fields : {};
const fields = {};
for (const f of fill) {
  if (Object.keys(fields).length >= 20) break;
  const name = f && f.name;
  if (typeof name !== 'string' || !Object.prototype.hasOwnProperty.call(filled, name)) continue;
  const value = filled[name];
  if (typeof value === 'string' && value.trim()) fields[name] = value.slice(0, 4000);
  else if (typeof value === 'number' && Number.isFinite(value)) fields[name] = value;
  else if (typeof value === 'boolean') fields[name] = value;
}
const filledAny = Object.keys(fields).length > 0;
const result = typeof read.draft === 'string' ? read.draft : text;
if (!result && !filledAny) {
  return failed('Claude returned an empty answer, so there is no result. Please do this step by hand.');
}

const usage = answer.usage || {};
return [{
  json: {
    status: 'success',
    metadata: filledAny ? { result, fields } : { result },
    // Lets Scallle cost the run.
    usage: {
      model: answer.model || null,
      input_tokens: usage.input_tokens ?? null,
      output_tokens: usage.output_tokens ?? null,
    },
  },
}];

// Say what went wrong in one plain sentence, for Scallle.
//
// The sentence is always one of the fixed ones below: n8n's own error text is
// never passed on, so no item data can reach Scallle this way. The full error
// stays on the failed step, in n8n's history of failed runs.
//
// Another step's error output can be wired here too (an Outlook or SharePoint
// node, say): Scallle is then told which step failed, by its name.

const failedStep = $prevNode.name;
const failed = (sentence) => [{ json: { status: 'error', error_message: sentence } }];

// The steps that make sure each run is worked once.
const CLAIM_STEPS = ['Claim this run', 'Find the first claim'];
if (CLAIM_STEPS.includes(failedStep)) {
  return failed("n8n couldn't check whether this run was already being worked (its 'Scallle run claims' data table), so the step wasn't done.");
}

// If you rename the AI step, rename it here too.
if (failedStep !== 'Do the work') {
  return failed("The '" + failedStep + "' step failed in n8n.");
}

const error = String($input.first().json.error || '');
return failed(
  /Authorization failed|Forbidden|credentials/i.test(error)
    ? "Anthropic refused the API key. Check the 'Anthropic — your own key' credential in n8n."
  : /too many requests/i.test(error)
    ? 'Anthropic is rate-limiting this API key. Please try the step again later.'
  : /could not be found/i.test(error)
    ? "Anthropic doesn't recognise the model named on the AI step. Check the model name in n8n."
  : /Bad request|invalid/i.test(error)
    ? "Anthropic rejected the request as invalid. Check the AI step's settings in n8n."
  : /service|gateway|unavailable|timed out|timeout|ECONN|ETIMEDOUT|socket|network/i.test(error)
    ? "Anthropic couldn't be reached or was overloaded. Please try the step again later."
  : 'The AI step failed in n8n.'
);

// Scallle couldn't be reached, or didn't take the report (after 2 tries, 5 s
// apart). Try again for about 10 minutes, as Scallle's code-project starter
// does: Scallle waits 20 minutes for a result before handing the step back to
// a person. Scallle answers 200 to a repeat, so sending again is safe.
//
// Each wait is a minute or less, so n8n keeps the run in memory while it
// waits instead of saving it (with the item) to its database.

const WAITS_SECONDS = [15, 30, 60, 60, 60, 60, 60, 60, 60, 60];
// Which report this is: the result, or the plain error.
const report = $prevNode.name;
// How many times this step has already run in this run.
const round = $runIndex;

if (round >= WAITS_SECONDS.length) {
  return [{ json: { keep_trying: false, report, wait_seconds: 0 } }];
}
return [{ json: { keep_trying: true, report, wait_seconds: WAITS_SECONDS[round] } }];
